package io.github.jimbozoomer.jugcraft.test;
import io.github.jimbozoomer.jugcraft.server.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import com.mojang.serialization.JsonOps;
public final class ServerUtilitiesTests {
    @GameTest public void regionBounds(GameTestHelper h){var tag=OperatorRegions.box(new BlockPos(10,20,30),new BlockPos(1,2,3));h.assertTrue(OperatorRegions.contains(tag,new BlockPos(1,2,3))&&OperatorRegions.contains(tag,new BlockPos(10,20,30)),"Inclusive reversed corners");h.assertTrue(!OperatorRegions.contains(tag,new BlockPos(0,2,3))&&!OperatorRegions.contains(tag,new BlockPos(10,21,30)),"Outside remains unprotected");h.succeed();}
    @GameTest public void warpPersistence(GameTestHelper h){var p=h.makeMockServerPlayerInLevel();ServerUtilities.save(p,"warp:test");var data=ServerUtilities.get(h.getLevel().getServer());var encoded=ServerUtilities.CODEC.encodeStart(net.minecraft.nbt.NbtOps.INSTANCE,data).getOrThrow();var decoded=ServerUtilities.CODEC.parse(net.minecraft.nbt.NbtOps.INSTANCE,encoded).getOrThrow();h.assertTrue(ServerUtilities.CODEC.encodeStart(net.minecraft.nbt.NbtOps.INSTANCE,decoded).getOrThrow().equals(encoded),"Destination data round-trips: "+encoded+" => "+ServerUtilities.CODEC.encodeStart(net.minecraft.nbt.NbtOps.INSTANCE,decoded).getOrThrow());h.succeed();}
    @GameTest public void nearbyTradeConstraints(GameTestHelper h){var a=h.makeMockServerPlayerInLevel();var b=h.makeMockServerPlayerInLevel();var at=h.absolutePos(new BlockPos(1,3,1));a.snapTo(at.getX(),at.getY(),at.getZ(),0,0);b.snapTo(at.getX()+1,at.getY(),at.getZ(),0,0);a.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND,2));b.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.GOLD_INGOT,5));h.assertTrue(NearbyTrade.nearby(a,b),"Nearby visible players eligible");h.assertTrue(!NearbyTrade.nearby(a,a),"Cannot trade yourself");h.assertTrue(NearbyTrade.offer(a,b)==1,"Offer begins without removing items");h.assertTrue(a.getMainHandItem().getCount()==2&&b.getMainHandItem().getCount()==5,"No escrow removes inventory");NearbyTrade.cancel(a);h.assertTrue(a.getMainHandItem().is(Items.DIAMOND)&&b.getMainHandItem().is(Items.GOLD_INGOT),"Cancel preserves items");b.snapTo(at.getX()+20,at.getY(),at.getZ(),0,0);h.assertTrue(!NearbyTrade.nearby(a,b)&&NearbyTrade.offer(a,b)==0,"Distant trade refused");h.succeed();}

    @GameTest public void permissionAndRegionProtection(GameTestHelper h)throws Exception{var p=h.makeMockServerPlayerInLevel();var server=h.getLevel().getServer();var dispatch=server.getCommands().getDispatcher();var normal=p.createCommandSourceStack();var op=server.createCommandSourceStack().withEntity(p).withSuppressedOutput();
        h.assertTrue(!dispatch.getRoot().getChild("protect").canUse(normal)&&!dispatch.getRoot().getChild("god").canUse(normal)&&!dispatch.getRoot().getChild("invsee").canUse(normal),"Ordinary player cannot access operator commands");
        var at=h.absolutePos(new BlockPos(1,3,1));p.snapTo(at.getX(),at.getY(),at.getZ(),0,0);dispatch.execute("protect pos1",op);p.snapTo(at.getX()+3,at.getY()+3,at.getZ()+3,0,0);dispatch.execute("protect pos2",op);String name="test_"+p.getUUID().toString().replace("-","");dispatch.execute("protect create "+name,op);
        h.assertTrue(OperatorRegions.protects(h.getLevel(),at)&&io.github.jimbozoomer.jugcraft.town.TownProtection.denies(p,h.getLevel(),at),"Cuboid rejects ordinary players through shared protection");h.assertTrue(io.github.jimbozoomer.jugcraft.town.TownProtection.shieldsBlock(h.getLevel(),at),"Explosion and automation shield participates");h.assertTrue(OperatorRegions.touchesChunk(h.getLevel(),(at.getX()>>4)<<4,(at.getZ()>>4)<<4),"Protected land cannot be sold as a new player claim");h.assertTrue(io.github.jimbozoomer.jugcraft.finance.LandRegistry.crossesBoundary(h.getLevel(),at.west(),at),"Fluids and unattended transfers respect operator boundary");dispatch.execute("protect remove "+name,op);h.assertTrue(!OperatorRegions.protects(h.getLevel(),at),"Removal clears region");h.succeed();}
    @GameTest public void tradeMutualConsentAndChangedOffer(GameTestHelper h){var a=h.makeMockServerPlayerInLevel();var b=h.makeMockServerPlayerInLevel();var at=h.absolutePos(new BlockPos(1,3,1));a.snapTo(at.getX(),at.getY(),at.getZ(),0,0);b.snapTo(at.getX()+1,at.getY(),at.getZ(),0,0);a.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND,2));b.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.GOLD_INGOT,5));
        h.assertTrue(NearbyTrade.offer(a,b)==1&&NearbyTrade.accept(a)==1,"First consent accepted");h.assertTrue(a.getMainHandItem().is(Items.DIAMOND),"One acceptance does not transfer");h.assertTrue(NearbyTrade.accept(b)==1,"Second consent transfers");h.assertTrue(a.getMainHandItem().is(Items.GOLD_INGOT)&&a.getMainHandItem().getCount()==5&&b.getMainHandItem().is(Items.DIAMOND)&&b.getMainHandItem().getCount()==2,"Exact stacks swapped once");h.assertTrue(NearbyTrade.accept(b)==0,"Cannot replay transfer");NearbyTrade.offer(a,b);NearbyTrade.accept(a);b.getMainHandItem().shrink(1);h.assertTrue(NearbyTrade.accept(b)==0&&a.getMainHandItem().is(Items.GOLD_INGOT),"Changed offer cancels rather than swaps");h.succeed();}

    @GameTest public void godModeAndUnsafeWarp(GameTestHelper h)throws Exception{var p=h.makeMockServerPlayerInLevel();var server=h.getLevel().getServer();var op=server.createCommandSourceStack().withEntity(p).withSuppressedOutput();var d=server.getCommands().getDispatcher();d.execute("god",op);h.assertTrue(!net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents.ALLOW_DAMAGE.invoker().allowDamage(p,p.damageSources().generic(),5),"God mode rejects incoming damage");d.execute("god",op);h.assertTrue(net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents.ALLOW_DAMAGE.invoker().allowDamage(p,p.damageSources().generic(),5),"God mode can be switched off");
        var at=h.absolutePos(new BlockPos(1,3,1));p.snapTo(at.getX()+.5,at.getY(),at.getZ()+.5,0,0);ServerUtilities.save(p,"warp:blocked");h.getLevel().setBlock(at,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);p.snapTo(at.getX()+4,at.getY(),at.getZ(),0,0);h.assertTrue(ServerUtilities.travel(p,"warp:blocked")==0,"Obstructed warp rejected");h.succeed();}
}
